import {hatSource} from './which-hat-content.mjs';
import {hatView,matchHats,describeHat,assessHat,validHatClaim,validHatAnswer,validHatSkip,startHats,resumeHats,editHat,supportHat,keepHat,answerHat,skipHat,removeHats} from './which-hat-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const pages={build:'Look and describe',questions:'Try a reader question',kept:'Kept discoveries'};
const hatLabel=(s,id)=>s.hats.find(h=>h.id===id)?.label??id;
const hatFacts=h=>`${h.size}, ${h.age}, ${h.color}; ${h.ribbon==='none'?'no ribbon':`${h.ribbon} ribbon`}`;
const readableClaims=w=>Array.isArray(w.claims)?w.claims.filter(validHatClaim):[];
const supportHas=(w,kind)=>Array.isArray(w.support?.concept)&&w.support.concept.some(x=>x.forId===(w.page==='questions'?w.question:w.target)&&x.kind===kind);

// Original, deliberately simple drawings. Printed model labels carry age and size.
function hatArt(h){const color=h.color==='red'?'#ae4d42':h.color==='blue'?'#44738b':'#7c756b',ribbon=h.ribbon==='gold'?'#e7b24b':'#294f83',big=h.size==='big';return `<svg class="hat-art" viewBox="0 0 160 110" aria-hidden="true" focusable="false"><path d="M15 91Q80 81 145 91" fill="none" stroke="#493b2f" stroke-width="3" stroke-linecap="round"/><g transform="${big?'translate(0 0)':'translate(20 15) scale(.75)'}"><path d="M43 76 61 24Q80 13 99 24l18 52" fill="${color}" stroke="#493b2f" stroke-width="3" stroke-linejoin="round"/><ellipse cx="80" cy="78" rx="62" ry="12" fill="${color}" stroke="#493b2f" stroke-width="3"/>${h.ribbon==='none'?'':`<path d="M48 59Q80 68 112 59l4 12Q80 80 44 71Z" fill="${ribbon}" stroke="#493b2f" stroke-width="2"/><path d="m112 63 18-6-4 13 8 10-22-9" fill="${ribbon}" stroke="#493b2f" stroke-width="2"/>`}<path d="m66 30-9 22" stroke="#fff6df" stroke-width="4" stroke-linecap="round" opacity=".55"/></g><circle cx="80" cy="8" r="5" fill="#b38a58" stroke="#493b2f" stroke-width="2"/></svg>`;}

function rack(w){const s=w.source,matches=matchHats(s,w.tiles);return `<section class="hats-rack" aria-labelledby="hat-rack-heading"><div class="hats-rack-title"><h2 id="hat-rack-heading">The Post Office hat pegs</h2><p>Fictional hats · all pegs are open</p></div><div class="hats-pegs" role="group" aria-label="Choose the requested hat">${s.hats.map(h=>`<button type="button" class="hat-peg${matches.includes(h.id)?' hat-matches':''}" data-hat-target="${esc(h.id)}" aria-pressed="${w.target===h.id}"><span class="hat-peg-label">${esc(h.label)}${w.target===h.id?' · requested':''}</span>${hatArt(h)}<strong>${esc(h.owner)}</strong><span class="hat-facts">${esc(hatFacts(h))}</span><span class="hat-match-label">${matches.includes(h.id)?'Fits your words':'Does not fit your words'}</span></button>`).join('')}</div><p class="hats-model-note">${esc(s.copy.limit)}</p></section>`;}

function support(w){const s=w.source,q=s.questions.find(q=>q.id===w.question),question=w.page==='questions';const entries=[['hint','Help',question?q.hint:s.copy.hint],['example','Different example',question?q.example:s.copy.example],['together','Work together',question?(q.together??q.explanation):s.copy.guided]];return `<section class="hats-support" aria-label="Optional support"><div class="hats-actions">${entries.map(([kind,label])=>btn(`data-hat-help="${kind}"`,label)).join('')}</div>${entries.filter(([kind])=>supportHas(w,kind)).map(([kind,label,text])=>`<aside class="hats-help" data-hat-help-shown="${kind}"><h3>${esc(label)}</h3><p>${esc(text)}</p>${kind==='together'?'<p>Working together is recorded as support for this turn.</p>':''}</aside>`).join('')}</section>`;}

function builder(w){const s=w.source,a=assessHat(s,w.tiles,w.target),before=w.tiles.filter(id=>!s.tiles.find(t=>t.id===id)?.after),after=w.tiles.filter(id=>s.tiles.find(t=>t.id===id)?.after);return `<h2 id="hat-heading" tabindex="-1">Look and describe</h2><p>${esc(s.copy.job)}</p><p class="hats-request">Requested: <strong>${esc(hatLabel(s,w.target))} · ${esc(s.hats.find(h=>h.id===w.target)?.owner)}</strong>. Tap a peg to choose another owner; your words stay in place.</p><p class="hats-live-fit" role="status" aria-live="polite"><strong>${a.matches.length} ${a.matches.length===1?'hat fits':'hats fit'}</strong> · ${esc(a.feedback)}</p><div class="hats-tiles" role="group" aria-label="Words to add or remove">${s.tiles.map(t=>btn(`data-hat-tile="${esc(t.id)}" aria-pressed="${w.tiles.includes(t.id)}"`,t.text)).join('')}</div><section class="hats-phrase-editor" aria-labelledby="hat-phrase-heading"><h3 id="hat-phrase-heading" tabindex="-1">Your description</h3><p class="hats-phrase" data-hat-phrase>${esc(describeHat(s,w.tiles))}</p>${w.tiles.length?`<details class="hats-movement"><summary>Move or remove selected words</summary><ol class="hats-ordered" aria-label="Selected words in phrase order">${[...before,...after].map(id=>{const t=s.tiles.find(t=>t.id===id),group=t.after?after:before,i=group.indexOf(id);return `<li><strong>${esc(t.text)}</strong><div class="hats-word-actions">${btn(`data-hat-earlier="${esc(id)}" ${i===0?'disabled':''} aria-label="${esc(`Move ${t.text} earlier`)}"`,'Move earlier')}${btn(`data-hat-later="${esc(id)}" ${i===group.length-1?'disabled':''} aria-label="${esc(`Move ${t.text} later`)}"`,'Move later')}${btn(`data-hat-remove-word="${esc(id)}" aria-label="${esc(`Remove ${t.text}`)}"`,'Remove')}</div></li>`;}).join('')}</ol></details>`:'<p>The frame is <strong>the … hat</strong>. With no describing words, every hat fits.</p>'}${btn('data-hat-clear','Clear this phrase')}</section><section class="hats-result" data-hat-outcome="${esc(a.outcome)}" aria-labelledby="hat-match-heading"><h3 id="hat-match-heading">Which hats fit?</h3><p class="hats-count"><strong>${a.matches.length}</strong> ${a.matches.length===1?'hat fits':'hats fit'} every word.</p><p>${esc(a.feedback)}</p>${a.matches.length?`<p>Matching pegs: ${a.matches.map(id=>esc(hatLabel(s,id))).join(', ')}.</p>`:''}${a.outcome==='target'?`<p class="hats-return">Returned to ${esc(s.hats.find(h=>h.id===w.target)?.owner)} at ${esc(hatLabel(s,w.target))}. Your words picked out the requested hat. ${esc(s.copy.goal)}</p>`:''}${btn('data-hat-keep','Keep this discovery',true)}</section><div class="hats-actions">${btn('data-hat-help="readback"','Read it back')}</div>${supportHas(w,'readback')?`<aside class="hats-help" data-hat-readback tabindex="-1"><h3>Read it back</h3><p class="hats-phrase">${esc(a.phrase)}</p><p>${esc(a.order==='usual'?s.copy.usual:s.copy.other)}</p><p>Changing word order does not change which hats fit these words.</p></aside>`:''}${support(w)}${hearButton(a.phrase,'Hear your description')}`;}

function supportNote(record){const h=record.helpBefore;if(h===undefined||h===null)return 'Earlier support was not observed in this saved record.';const forId=record.itemId??record.target,concept=Array.isArray(h.concept)?h.concept.filter(x=>x.forId===forId):[],reading=Array.isArray(h.reading)?h.reading.filter(x=>x.forId===forId):[];return `${h.observed===true?'':'Earlier support was not observed; these later requests are known. '}Support requests before this result for this turn: ${concept.length} concept; ${reading.length} reading. The rack and live count were available.`;}
function savedAnswer(r,label){const q=r.source.questions.find(q=>q.id===r.itemId);return `<article class="hats-saved-answer"><h4>${esc(label)}</h4><details><summary>Original question and ordered choices</summary><p>${esc(q.context)}</p><p>${esc(q.prompt)}</p><ol>${q.choices.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol></details><p>Choice: <strong>${esc(r.source.questions.find(q=>q.id===r.itemId)?.choices.find(c=>c.id===r.choice)?.text??r.choice)}</strong></p><p>${esc(r.feedback)}</p><p class="hats-evidence">${esc(supportNote(r))}</p></article>`;}
function answerHistory(w,itemId){const a=w.answers?.[itemId];if(!a||typeof a!=='object')return '';const first=validHatAnswer(a.first,itemId)?a.first:null,latest=validHatAnswer(a.latest,itemId)?a.latest:null,skip=validHatSkip(a.skipped,itemId)?a.skipped:null;return `<div class="hats-answer-history">${first?savedAnswer(first,'First response · kept as answered'):''}${latest&&JSON.stringify(latest)!==JSON.stringify(first)?savedAnswer(latest,'Latest response'):''}${skip?`<p>Skipped this question. ${esc(supportNote(skip))}</p>`:''}${!first&&!latest&&!skip?'<p>An earlier entry cannot be displayed here. Its exact saved form stays in your notes.</p>':''}</div>`;}

function questions(w){const s=w.source,q=s.questions.find(q=>q.id===w.question),a=w.answers?.[q.id],latest=validHatAnswer(a?.latest,q.id)?a.latest:validHatAnswer(a?.first,q.id)?a.first:null;return `<h2 id="hat-heading" tabindex="-1">Try a reader question</h2><p>Choose any question. You can revise an answer, skip, or ask for support.</p><div class="hats-question-picker" role="group" aria-label="Choose a reader question">${s.questions.map((item,i)=>btn(`data-hat-question="${esc(item.id)}" aria-pressed="${q.id===item.id}"`,`Question ${i+1}`)).join('')}</div><section class="hats-question" aria-labelledby="hat-question-heading"><p class="hats-context">${esc(q.context)}</p><h3 id="hat-question-heading" tabindex="-1">${esc(q.prompt)}</h3><div class="hats-answers" role="group" aria-label="Answer choices">${q.choices.map(c=>btn(`data-hat-answer="${esc(c.id)}" aria-pressed="${latest?.choice===c.id}"`,c.text)).join('')}</div>${btn('data-hat-skip','Skip this question')}${answerHistory(w,q.id)}</section>${support(w)}${hearButton(`${q.context} ${q.prompt} ${q.choices.map(c=>c.text).join('. ')}`,'Hear this question and choices')}`;}

function keptClaim(c,i){return `<article class="hats-kept-claim"><h3>Discovery ${i+1} · ${esc(hatLabel(c.source,c.target))}</h3><p class="hats-phrase">${esc(c.phrase)}</p><p>${c.matches.length} ${c.matches.length===1?'hat fit':'hats fit'}: ${c.matches.length?c.matches.map(id=>esc(hatLabel(c.source,id))).join(', '):'no matching pegs'}.</p><p>${esc(c.feedback)}</p><p>Recorded order: ${c.order==='usual'?'usual':'another understandable order'}.</p><p class="hats-evidence">${esc(supportNote(c))}</p><details><summary>Original source for this discovery</summary><p>Requested: ${esc(hatLabel(c.source,c.target))}. Words: ${c.tiles.length?c.tiles.map(id=>esc(c.source.tiles.find(t=>t.id===id)?.text??id)).join(' · '):'no describing words'}.</p><ul>${c.source.hats.map(h=>`<li>${esc(h.label)} · ${esc(h.owner)}: ${esc(hatFacts(h))}</li>`).join('')}</ul></details></article>`;}
function kept(w,notes=false){const claims=readableClaims(w);return `<h2${notes?'':' id="hat-heading" tabindex="-1"'}>Kept discoveries</h2><p>Each discovery keeps its own words, source and original result. Any outcome can help you notice something.</p>${claims.length?claims.map(keptClaim).join(''):'<p>No discoveries kept yet. Build a description and choose Keep this discovery.</p>'}<h3>Reader responses</h3>${w.source.questions.map(q=>w.answers?.[q.id]?`<details><summary>${esc(q.prompt)}</summary>${answerHistory(w,q.id)}</details>`:'').join('')||'<p>No reader responses yet.</p>'}<p class="hats-evidence">Unreadable saved entries stay exact in your notebook download. Later help does not change earlier responses.</p>`;}

export const hatsEntry=()=>'<aside class="hats-entry"><h2>Which Hat?</h2><p>Six hats, one requested peg. Choose words that help a reader find it.</p><a class="secondary" href="#post/descriptions">Visit the hat pegs</a></aside>';

export function hatsPage(state){const v=hatView(state),w=v.work,s=w?.source??hatSource;const head=`<div class="hats-page" data-hats-root><header><a class="back" href="#post">Willow Post Office</a><p class="hats-eyebrow">A little language workshop</p><h1>Which Hat?</h1><p>Words that help a reader find one thing.</p></header>`;if(v.status==='unavailable')return head+'<section class="hats-turn"><h2 id="hat-heading" tabindex="-1">Earlier hat work is retained</h2><p>This version cannot edit that saved format. Download your notes; the other destinations stay open.</p><a class="secondary" href="#notes">Open notes</a></section></div>';
 const visits=v.visits.length?`<details class="hats-visits"><summary>Your hat visits</summary><div class="hats-actions">${v.visits.map(x=>x.readable?btn(`data-hat-resume="${esc(x.id)}" aria-pressed="${v.root?.current===x.id}"`,`${x.title} · ${x.id}`):'<p>An unreadable visit stays in your notebook download.</p>').join('')}</div></details>`:'';
 if(!w)return head+`<section class="hats-turn hats-intro"><div class="hats-welcome-art">${s.hats.slice(0,3).map(h=>hatArt(h)).join('')}</div><h2 id="hat-heading" tabindex="-1">One peg. Your choice of words.</h2><p>${esc(s.copy.welcome)}</p><p>${esc(s.copy.job)}</p>${btn('data-hat-start','Start describing',true)}<p class="hats-model-note">${esc(s.copy.limit)}</p></section>${visits}<p id="hat-status" role="status" tabindex="-1"></p></div>`;
 return head+`<nav class="hats-pages" aria-label="Which Hat turns">${Object.entries(pages).map(([key,title])=>btn(`data-hat-page="${key}" aria-current="${w.page===key?'step':'false'}"`,title)).join('')}</nav>${visits}<div class="hats-work">${rack(w)}<section class="hats-turn">${w.page==='build'?builder(w):w.page==='questions'?questions(w):kept(w)}</section></div><p class="hats-model-note">${esc(s.copy.scaffold)}</p><details class="hats-visits"><summary>Another visit or make space</summary><p>A new visit retains all earlier work. Up to eight visits can be kept. Download notes before removing a visit you want to save.</p><div class="hats-actions">${btn('data-hat-start','Start a new visit')}${v.visits.filter(x=>x.readable).map(x=>btn(`data-hat-delete="${esc(x.id)}"`,`Remove ${x.id}`)).join('')}</div><a class="secondary" href="#notes">Open notebook and download</a></details><p id="hat-status" role="status" tabindex="-1"></p><footer><a class="secondary" href="#pathways/english">Other English explorations</a><a class="secondary" href="#post">Return to the Post Office</a></footer></div>`;
}

export function hatsNotes(state){if(!Object.hasOwn(state,'descriptions'))return '';const v=hatView(state);return `<details class="panel hats-notes"><summary>Which Hat? · descriptions and reader responses</summary><p>A made-up visual language model. The rack and live count are scaffolds; saved results do not demonstrate independent grammar, reading, writing or mastery. Original sources, first responses and support observations are retained.</p>${v.visits.filter(x=>x.readable).map(x=>{const w=v.root.visits[x.id];return `<h3>Visit ${esc(x.id)}</h3><p>Current description: ${esc(describeHat(w.source,w.tiles))}</p>${kept(w,true)}`;}).join('')}<details><summary>Exact saved sources and work, including retained entries</summary><pre>${esc(JSON.stringify(state.descriptions,null,2))}</pre></details></details>`;}

export function bindHats(state,{save,render,focus,canExport,explorerId,isActive}={}){const root=document.querySelector('[data-hats-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport};const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());const say=text=>{const node=root.querySelector('#hat-status');if(node)node.textContent=text;};const act=(el,fn,message='',target='#hat-heading')=>{if(!live(el))return;const r=fn();if(!r?.ok){say(r?.error??'This change could not be saved. Download your notebook to retain your work.');return;}const movementOpen=root.querySelector('.hats-movement')?.open===true;stopSpeech();save?.();render?.();const panel=document.querySelector('[data-hats-root] .hats-movement');if(panel&&movementOpen)panel.open=true;const status=document.querySelector('#hat-status');if(status)status.textContent=message;focus?.(document.querySelector(target)?.disabled?'#hat-phrase-heading':target);};const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 // Selectors use rendered ordinal positions, so retired source IDs need no CSS escaping.
 const sameButton=(selector,b)=>`${selector}:nth-of-type(${[...b.parentElement.children].filter(x=>x.tagName===b.tagName).indexOf(b)+1})`;
 on('[data-hat-start]',b=>act(b,()=>startHats(state,o),'New visit opened. Earlier visits are retained.'));
 on('[data-hat-resume]',b=>act(b,()=>resumeHats(state,b.dataset.hatResume,o),'Visit resumed with its original source.'));
 on('[data-hat-page]',b=>act(b,()=>editHat(state,'page',b.dataset.hatPage,o)));
 on('[data-hat-target]',b=>act(b,()=>editHat(state,'target',b.dataset.hatTarget,o),'Requested peg changed. Your description is retained.',sameButton('[data-hat-target]',b)));
 on('[data-hat-tile]',b=>act(b,()=>editHat(state,'tile',b.dataset.hatTile,o),'Description saved.',sameButton('[data-hat-tile]',b)));
 for(const [attr,kind] of [['earlier','earlier'],['later','later'],['remove-word','remove']])on(`[data-hat-${attr}]`,b=>act(b,()=>editHat(state,kind,b.getAttribute(`data-hat-${attr}`),o),'Description saved.',kind==='remove'?'#hat-phrase-heading':`[data-hat-${attr}="${b.getAttribute(`data-hat-${attr}`)}"]`));
 on('[data-hat-clear]',b=>act(b,()=>editHat(state,'clear',null,o),'This phrase is clear. All hats fit the frame.','#hat-phrase-heading'));
 on('[data-hat-question]',b=>act(b,()=>editHat(state,'question',b.dataset.hatQuestion,o),'Question opened.','#hat-question-heading'));
 on('[data-hat-answer]',b=>act(b,()=>answerHat(state,b.dataset.hatAnswer,o),'Response saved. Your first response stays as answered.','#hat-question-heading'));
 on('[data-hat-skip]',b=>act(b,()=>skipHat(state,o),'Skip recorded. You may return to this question.','#hat-question-heading'));
 on('[data-hat-keep]',b=>act(b,()=>keepHat(state,o),'Discovery kept with its original result.','[data-hat-keep]'));
 on('[data-hat-help]',b=>act(b,()=>supportHat(state,b.dataset.hatHelp,o),'Support request saved.',b.dataset.hatHelp==='readback'?'[data-hat-readback]':'#hat-heading'));
 on('[data-hat-delete]',b=>{if(window.confirm(`Remove visit ${b.dataset.hatDelete}, including its descriptions, reader responses and support records? Download notebook notes first if you want to retain them.`))act(b,()=>removeHats(state,b.dataset.hatDelete,true,o),'Selected visit removed.');});
 // Capture runs before the host's speech handler, committing the request before any audio.
 root.addEventListener('click',e=>{const b=e.target.closest?.('[data-speak]');if(!b)return;if(!live(b)){e.stopImmediatePropagation();return;}const r=supportHat(state,'audio',o);if(!r?.ok){e.stopImmediatePropagation();say(r?.error??'Listening could not be recorded. Download notes and try again.');return;}save?.();},true);
}
